            case "close": return ReadOpClose(json);
            case "focus": return ReadOpFocus(json);
            case "url": return ReadOpUrl(json);
            case "navigate": return ReadOpNavigate(json);
            case "navigate_external": return ReadOpNavigateExternal(json);
            case "invalidate": return ReadOpInvalidate(json);
            case "device": return ReadOpDevice(json);
            case "reload": return new OpReload();
            case "signed_out": return new OpSignedOut();
            default:
                return new OpUnknown
