    public sealed record WhenUnknown : When
    {
        public required string Tag { get; init; }
    }

    /// <summary>Reads a <c>When</c> by its <c>t</c>.</summary>
    public static When ReadWhen(JsonElement json)
    {
        if (json.ValueKind != JsonValueKind.Object)
        {
            return new WhenUnknown { Tag = "" };
        }

        string tag = Reading.Tag(json, "t");
        switch (tag)
        {
            case "at": return ReadWhenAt(json);
            case "after": return ReadWhenAfter(json);
            case "daily": return ReadWhenDaily(json);
            default:
                return new WhenUnknown
                {
                    Tag = tag,
                };
        }
    }

    /// <summary>Writes a <c>When</c>, its <c>t</c> first.</summary>
    public static void WriteWhen(Utf8JsonWriter w, When v)
    {
        w.WriteStartObject();
        switch (v)
        {
            case WhenAt x:
                w.WriteString("t", "at");
                WriteWhenAtBody(w, x);
                break;
            case WhenAfter x:
                w.WriteString("t", "after");
                WriteWhenAfterBody(w, x);
                break;
            case WhenDaily x:
                w.WriteString("t", "daily");
                WriteWhenDailyBody(w, x);
                break;
            case WhenUnknown x:
                w.WriteString("t", x.Tag);
                break;
            default:
                throw new ArgumentException("a When this build does not know", nameof(v));
        }
        w.WriteEndObject();
    }

