    /// <summary><c>Zone</c>.</summary>
    public sealed record Zone
    {
        public Colour? Colour { get; init; }
        public required double From { get; init; }
        public string? Label { get; init; }
        public required double To { get; init; }
    }

    /// <summary>Reads a <c>Zone</c>.</summary>
    public static Zone ReadZone(JsonElement json)
    {
        Reading.ExpectObject(json);
        return new Zone
        {
            Colour = Reading.Opt<Colour>(json, "colour", ReadColour),
            From = Reading.Required<double>(json, "from", Reading.Double),
            Label = Reading.Opt<string>(json, "label", Reading.Text),
            To = Reading.Required<double>(json, "to", Reading.Double),
        };
    }

    /// <summary>Writes a <c>Zone</c>.</summary>
    public static void WriteZone(Utf8JsonWriter w, Zone v)
    {
        w.WriteStartObject();
        WriteZoneBody(w, v);
        w.WriteEndObject();
    }

    private static void WriteZoneBody(Utf8JsonWriter w, Zone v)
    {
        if (v.Colour is not null) { w.WritePropertyName("colour"); WriteColour(w, v.Colour); }
        w.WritePropertyName("from"); w.WriteNumberValue(v.From);
        if (v.Label is not null) { w.WritePropertyName("label"); w.WriteStringValue(v.Label); }
        w.WritePropertyName("to"); w.WriteNumberValue(v.To);
    }
